CREATE FUNCTION app.pilot_summary() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=pg_catalog,public,pg_temp AS $$
DECLARE result jsonb;
BEGIN
 IF NOT app.is_platform_admin() THEN RAISE EXCEPTION 'FORBIDDEN';END IF;
 WITH orgs AS(SELECT * FROM public.organizations),activations AS(SELECT organization_id,(metadata->>'studentId')::uuid student_id,min(created_at) accepted_at FROM public.audit_logs WHERE action='student.invitation_accepted' AND metadata->>'studentId' IS NOT NULL GROUP BY organization_id,metadata->>'studentId'),sessions AS(SELECT s.* FROM public.workout_sessions s WHERE s.state='completed' AND EXISTS(SELECT 1 FROM public.workout_sets r WHERE r.organization_id=s.organization_id AND r.session_id=s.id AND r.state='recorded')),debts AS(SELECT i.total_pyg+coalesce((SELECT sum(amount_pyg) FROM public.saas_adjustments a WHERE a.invoice_id=i.id),0)-coalesce((SELECT sum(amount_pyg) FROM public.saas_payments p WHERE p.invoice_id=i.id AND NOT EXISTS(SELECT 1 FROM public.saas_payment_reversals r WHERE r.payment_id=p.id)),0) balance FROM public.saas_invoices i)
 SELECT jsonb_build_object('windowDays',28,'computedAt',now(),'organizations',(SELECT count(*) FROM orgs),'newOrganizations',(SELECT count(*) FROM orgs WHERE created_at>=now()-interval '28 days'),'firstProgramIn24h',(SELECT count(*) FROM orgs o WHERE o.created_at>=now()-interval '28 days' AND EXISTS(SELECT 1 FROM public.program_versions v WHERE v.organization_id=o.id AND v.created_at BETWEEN o.created_at AND o.created_at+interval '24 hours')),'enabledStudents',(SELECT count(*) FROM public.students s JOIN orgs o ON o.id=s.organization_id WHERE s.status='active' AND o.status IN ('active','trial')),'activatedStudents',(SELECT count(*) FROM activations WHERE accepted_at>=now()-interval '28 days'),'firstSessionIn7d',(SELECT count(*) FROM activations a WHERE a.accepted_at>=now()-interval '28 days' AND EXISTS(SELECT 1 FROM sessions s WHERE s.organization_id=a.organization_id AND s.student_id=a.student_id AND s.completed_at BETWEEN a.accepted_at AND a.accepted_at+interval '7 days')),'completedSessions',(SELECT count(*) FROM sessions WHERE completed_at>=now()-interval '28 days'),'outstandingPyg',(SELECT coalesce(sum(balance),0) FROM debts),'issuedAccounts',(SELECT count(*) FROM public.saas_invoices))INTO result;
 RETURN result;
END $$;
REVOKE ALL ON FUNCTION app.pilot_summary() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION app.pilot_summary() TO forma_api;
